#include "vertex_stream.hpp"
#include <cassert>
int main(){ofo::VertexStream s(1024);auto a=s.allocate(168,28);assert(a.offset==0&&a.discard);auto b=s.allocate(264,44);assert(b.offset==176&&!b.discard);auto c=s.allocate(572,44);assert(c.offset==440&&!c.discard);auto d=s.allocate(28,28);assert(d.offset==0&&d.discard);s.begin_frame();assert(s.allocate(44,44).discard);try{s.allocate(1056,44);assert(false);}catch(const std::length_error&){}assert(s.allocate(44,44).offset==44);try{s.allocate(43,44);assert(false);}catch(const std::invalid_argument&){}size_t end=0,discards=0;for(int i=0;i<2000;i++){size_t stride=i%2?28:44,bytes=stride*(1+i%11);auto q=s.allocate(bytes,stride);assert(q.offset%stride==0&&q.offset+bytes<=1024);if(q.discard){end=0;++discards;}assert(q.offset>=end);end=q.offset+bytes;}assert(discards>1);}
